    store = world({"alice": "Alice", "bob": "Bob"}, {"alice": ["bob"], "bob": ["alice"]})
    store.settings["bob"] = {"v": 1, "at": "x", "settings": {"sev_look": ["dino", "headphones"], "accent": "teal"}, "rev": 1}
    cl = new_client(store, "alice")
